57	import org.springframework.samples.petclinic.service.ClinicService;
58	import org.springframework.security.access.prepost.PreAuthorize;
59	import org.springframework.web.bind.annotation.CrossOrigin;
60	import org.springframework.web.bind.annotation.RequestMapping;
61	import org.springframework.web.bind.annotation.RestController;
62	import org.springframework.web.util.UriComponentsBuilder;
63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
77	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
78	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
79	     */
80	    private static final Pattern EMAIL_PATTERN =
81	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
82	
83	    /**
84	     * Disposable email domains that are refused on create. An email whose domain (the part after the
85	     * {@code @}, compared case-insensitively) is in this set is rejected with a 400, since such
86	     * addresses are throwaway and unsuitable for contacting an owner.
87	     */
88	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
89	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
90	
91	    /**
92	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
93	     * memberId, the registrationDate and the membershipLevel is emitted through this logger.
94	     */
95	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
96	
97	    /**
98	     * Dedicated notification logger. On a successful create a welcome notification carrying the owner
99	     * id and the memberId is enqueued by emitting a line through this logger.
100	     */
101	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
102	
103	    /**
104	     * Monotonically increasing sequence number stamped on each {@link OwnerCreatedEvent}, shared
105	     * across every create in this process so consumers can totally order the emitted events.
106	     */
107	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_SEQ =
108	        new java.util.concurrent.atomic.AtomicLong();
109	
110	    /**
111	     * Immutable structured audit event emitted through {@link #AUDIT} on a successful owner create.
112	     * <p>This is the schema-version-2 event: it carries an explicit {@code schemaVersion} of 2 and the
113	     * owner's {@code ownerSegment} recomputed from the version-2 identity. The identifier it carries is
114	     * the owner's <em>current</em> primary identifier — its unified version-2 {@code memberId} — so a
115	     * downstream consumer always reads the live primary key from the one {@code memberId} field. See
116	     * {@link #primaryIdentifier(Owner)}.
117	     */
118	    private record OwnerCreatedEvent(long seq, Integer ownerId, String identifier, Integer membershipLevel,
119	                                     String ownerSegment) {
120	
121	        /** The schema version of this audit event. */
122	        private static final int SCHEMA_VERSION = 2;
123	
124	        String toJson() {
125	            return "{\"seq\":" + seq
126	                + ",\"schemaVersion\":" + SCHEMA_VERSION
127	                + ",\"ownerId\":" + ownerId
128	                + ",\"memberId\":" + jsonString(identifier)
129	                + ",\"membershipLevel\":" + membershipLevel
130	                + ",\"ownerSegment\":" + jsonString(ownerSegment)
131	                + ",\"event\":\"OWNER_CREATED\"}";
132	        }
133	
134	        private static String jsonString(String s) {
135	            if (s == null) {
136	                return "null";
137	            }
138	            StringBuilder sb = new StringBuilder(s.length() + 2).append('"');
139	            for (int i = 0; i < s.length(); i++) {
140	                char c = s.charAt(i);
141	                switch (c) {
142	                    case '"' -> sb.append("\\\"");
143	                    case '\\' -> sb.append("\\\\");
144	                    case '\n' -> sb.append("\\n");
145	                    case '\r' -> sb.append("\\r");
146	                    case '\t' -> sb.append("\\t");
147	                    default -> sb.append(c);
148	                }
149	            }
150	            return sb.append('"').toString();
151	        }
152	    }
153	
154	    /**
155	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create, so a repeated
156	     * create carrying a key already in this map returns the originally created owner (200) instead of
157	     * creating a duplicate. Keys are supplied by the caller and are process-wide.
158	     */
159	    private final java.util.Map<String, Integer> idempotencyKeys = new java.util.concurrent.ConcurrentHashMap<>();
160	
161	    private final ClinicService clinicService;
162	
163	    private final OwnerMapper ownerMapper;
164	
165	    private final PetMapper petMapper;
166	
167	    private final VisitMapper visitMapper;
168	
169	    public OwnerRestControllerV1(ClinicService clinicService,
170	                                 OwnerMapper ownerMapper,
171	                                 PetMapper petMapper,
172	                                 VisitMapper visitMapper) {
173	        this.clinicService = clinicService;
174	        this.ownerMapper = ownerMapper;
175	        this.petMapper = petMapper;
176	        this.visitMapper = visitMapper;
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
182	        Collection<Owner> owners;
183	        if (lastName != null) {
184	            owners = this.clinicService.findOwnerByLastName(lastName);
185	        } else {
186	            owners = this.clinicService.findAllOwners();
187	        }
188	        if (owners.isEmpty()) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
192	    }
193	
194	    /**
195	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
196	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
197	     */
198	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
199	        List<String> missing = new ArrayList<>();
200	        if (isBlank(ownerFieldsDto.getFirstName())) {
201	            missing.add("firstName");
202	        }
203	        if (isBlank(ownerFieldsDto.getLastName())) {
204	            missing.add("lastName");
205	        }
206	        if (isBlank(ownerFieldsDto.getAddress())) {
207	            missing.add("address");
208	        }
209	        if (isBlank(ownerFieldsDto.getCity())) {
210	            missing.add("city");
211	        }
212	        if (isBlank(ownerFieldsDto.getTelephone())) {
213	            missing.add("telephone");
214	        }
215	        if (!missing.isEmpty()) {
216	            throw new RequiredFieldsMissingException(missing);
217	        }
218	    }
219	
220	    private static boolean isBlank(String value) {
221	        return value == null || value.isBlank();
222	    }
223	
224	    /**
225	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
226	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
227	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
228	     * normalized value is what gets stored, returned and used for every address comparison; a value
229	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
230	     * rejects it.
231	     *
232	     * @param address the raw address as supplied by the caller, may be {@code null}
233	     * @return the normalized address ({@code ""} when blank or {@code null})
234	     */
235	    private static String normalizeAddress(String address) {
236	        if (address == null) {
237	            return "";
238	        }
239	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
240	        if (collapsed.isEmpty()) {
241	            return "";
242	        }
243	        String[] tokens = collapsed.split(" ");
244	        StringBuilder sb = new StringBuilder(collapsed.length());
245	        for (int i = 0; i < tokens.length; i++) {
246	            String token = tokens[i];
247	            switch (token) {
248	                case "ST" -> token = "STREET";
249	                case "RD" -> token = "ROAD";
250	                case "AVE" -> token = "AVENUE";
251	                default -> { }
252	            }
253	            if (i > 0) {
254	                sb.append(' ');
255	            }
256	            sb.append(token);
257	        }
258	        return sb.toString();
259	    }
260	
261	    /**
262	     * Resolves and normalizes the owner's address on create, supporting both the structured form
263	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
264	     * backward compatibility. Whichever address fields are supplied are normalized (see
265	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
266	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
267	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
268	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
269	     * {@code address}. The normalized structured fields are written back so they are stored and
270	     * returned, and the composed value is written to {@code address} so everything that reads the
271	     * address (the household hash, postcode validation and locality) uses the structured fields when
272	     * present, falling back to the flat address. When neither form supplies an address the composed
273	     * {@code address} is blank, so the required-field check rejects it.
274	     *
275	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
276	     */
277	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
278	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
279	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
280	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
281	        String composed;
282	        if (!line1.isEmpty()) {
283	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
284	        } else {
285	            composed = flat;
286	        }
287	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
288	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
289	        ownerFieldsDto.setAddress(composed);
290	    }
291	
292	    /**
293	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
294	     * A leading {@code +} and its country code are kept as given; otherwise the country code
295	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
296	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
297	     * is recognized the national number must have the exact length that code requires ({@code +61}
298	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
299	     * returned.
300	     *
301	     * @param telephone the raw telephone as supplied by the caller
302	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
303	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
304	     *     national-number length is wrong for its country code
305	     */
306	    private static String normalizeTelephone(String telephone) {
307	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
308	        String e164;
309	        if (cleaned.startsWith("+")) {
310	            e164 = "+" + cleaned.substring(1);
311	        } else {
312	            String national = cleaned;
313	            if (national.startsWith("0")) {
314	                national = national.substring(1);
315	            }
316	            e164 = "+61" + national;
317	        }
318	        String digits = e164.substring(1);
319	        if (!digits.matches("\\d{8,15}")) {
320	            throw new InvalidTelephoneException(
321	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
322	        }
323	        if (digits.startsWith("61")) {
324	            requireNationalLength(digits.substring(2), 9, "+61");
325	        } else if (digits.startsWith("1")) {
326	            requireNationalLength(digits.substring(1), 10, "+1");
327	        }
328	        return e164;
329	    }
330	
331	    /**
332	     * Enforces that the national portion of an E.164 number has the exact number of digits its
333	     * country code requires.
334	     *
335	     * @param national the national-number digits (the part after the country code)
336	     * @param expected the exact national-number length the country code requires
337	     * @param countryCode the country code, for the error message
338	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
339	     */
340	    private static void requireNationalLength(String national, int expected, String countryCode) {
341	        if (national.length() != expected) {
342	            throw new InvalidTelephoneException(
343	                "Telephone with country code '" + countryCode + "' must have " + expected
344	                    + " national digits");
345	        }
346	    }
347	
348	    /**
349	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
350	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
351	     *
352	     * @param email the raw email as supplied by the caller, may be {@code null}
353	     * @return the lower-cased email, or {@code null} when none was supplied
354	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
355	     */
356	    private static String normalizeEmail(String email) {
357	        if (email == null || email.isBlank()) {
358	            return null;
359	        }
360	        String trimmed = email.trim();
361	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
362	            throw new InvalidEmailException("Email must be a syntactically valid address");
363	        }
364	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
365	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
366	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
367	            throw new InvalidEmailException("Email domain is not allowed");
368	        }
369	        return lowerCased;
370	    }
371	
372	    /**
373	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
374	     * email and household checks. The key is the lower-case hex SHA-256 of
375	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty segment
376	     * for an absent telephone or email. Because the telephone is part of the key, two owners that
377	     * differ in any one segment (for example two members of the same household with different
378	     * telephones) produce different keys and are therefore not hard duplicates.
379	     *
380	     * @param normalizedTelephone the E.164 telephone of the owner
381	     * @param email the lower-cased email of the owner, may be {@code null}
382	     * @param lastName the last name of the owner, reduced to its Soundex code, may be {@code null}
383	     * @return the derived identity key
384	     */
385	    private static String deriveIdentityKey(String normalizedTelephone, String email, String lastName) {
386	        return org.springframework.samples.petclinic.util.IdentityKeys.identityKey(
387	            normalizedTelephone, email, lastName);
388	    }
389	
390	    /**
391	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
392	     * owner. This one check replaces the former separate telephone, email and household duplicate
393	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
394	     * segment are both allowed. Each existing owner's key is derived from its stored, already
395	     * normalized telephone, email and household identifier.
396	     *
397	     * @param identityKey the derived identity key of the owner being created
398	     * @throws DuplicateIdentityException if another owner already has this identity key
399	     */
400	    /**
401	     * The existing owners considered by the create endpoint's duplicate and identity checks:
402	     * every owner that is not soft-deleted. A soft-deleted owner retains its row but is ignored
403	     * here, so a create that would otherwise be blocked by it is allowed.
404	     *
405	     * @return a stream of the owners not flagged deleted
406	     */
407	    private java.util.stream.Stream<Owner> activeOwners() {
408	        return this.clinicService.findAllOwners().stream()
409	            .filter(existing -> !existing.isDeleted());
410	    }
411	
412	    private void rejectDuplicateIdentity(String identityKey) {
413	        boolean inUse = activeOwners()
414	            .anyMatch(existing -> identityKey.equals(
415	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())));
416	        if (inUse) {
417	            throw new DuplicateIdentityException(
418	                "An owner with the same identity key already exists");
419	        }
420	    }
421	
422	    /**
423	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
424	     * not a hard identity duplicate (its {@code identityKey} differs) but shares the phonetic code of
425	     * this owner's last name (its Soundex) and its postcode. Because the telephone is part of the
426	     * identity key, two owners with the same surname and postcode but different telephones are no
427	     * longer hard duplicates — they surface here as a soft match instead. When the postcode is absent
428	     * no owner can share it, so there is never a match. When several existing owners qualify the one
429	     * with the lowest id is returned, so the result is deterministic.
430	     *
431	     * @param lastName the last name of the owner being created
432	     * @param postcode the postcode of the owner being created, may be {@code null}
433	     * @param identityKey the derived identity key of the owner being created
434	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
435	     */
436	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String identityKey) {
437	        if (postcode == null || postcode.isBlank()) {
438	            return null;
439	        }
440	        String soundex = org.springframework.samples.petclinic.util.IdentityKeys.soundex(lastName);
441	        return activeOwners()
442	            .filter(existing -> soundex.equals(
443	                org.springframework.samples.petclinic.util.IdentityKeys.soundex(existing.getLastName())))
444	            .filter(existing -> postcode.equals(existing.getPostcode()))
445	            .filter(existing -> !identityKey.equals(
446	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
447	            .map(Owner::getId)
448	            .filter(java.util.Objects::nonNull)
449	            .min(Integer::compareTo)
450	            .orElse(null);
451	    }
452	
453	    /**
454	     * Derives the stable household identifier for an owner from its last name and postcode. The value
455	     * is the first twelve hex characters of the SHA-256 of
456	     * {@code normalizedLastName + '|' + postcode + '|' + "V2"} (the last name normalized
457	     * case-insensitively with surrounding whitespace trimmed; an absent postcode contributes the empty
458	     * string; the fixed {@code 'V2'} version tag is mixed in). Because it is a pure function of those two fields, every
459	     * owner with the same last name and postcode is assigned the same identifier automatically, without
460	     * any existing record having to be updated.
461	     *
462	     * @param lastName the last name of the owner being created
463	     * @param postcode the postcode of the owner being created, may be {@code null}
464	     * @return the stable household identifier
465	     */
466	    private static String householdId(String lastName, String postcode) {
467	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode)
468	            + "|" + org.springframework.samples.petclinic.util.IdentityKeys.VERSION_TAG;
469	        return sha256HexPrefix(key, 12);
470	    }
