478	    /**
479	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
480	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
481	     * trimmed. The count reflects the
482	     * state before the new owner is persisted, so it excludes the owner being created.
483	     *
484	     * @param city the city of the owner being created
485	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
486	     */
487	    private void rejectCityAtCapacity(String city) {
488	        String normalizedCity = normalizeName(city);
489	        long ownersInCity = this.clinicService.findAllOwners().stream()
490	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
491	            .count();
492	        if (ownersInCity >= CITY_CAPACITY) {
493	            throw new CityAtCapacityException(
