574	    /** Fixed public holidays the business-day roll skips. */
575	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
576	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
577	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
578	        LocalDate.parse("2026-12-28"));
