580	    /**
581	     * Rolls a registration date forward to a business day: any date landing on a Saturday, Sunday or
582	     * listed public holiday is advanced one day at a time until it reaches the next non-holiday
583	     * weekday, and any other weekday is returned unchanged.
584	     *
585	     * @param date the effective registration date, supplied or defaulted to the server date
586	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
587	     */
588	    private static LocalDate toBusinessDay(LocalDate date) {
589	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
590	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
591	                || PUBLIC_HOLIDAYS.contains(date)) {
592	            date = date.plusDays(1);
593	        }
594	        return date;
595	    }
