597	    /**
598	     * Builds the unified member id assigned to an owner on create, formatted
599	     * {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is the version-2 region code — the region
600	     * derived from the owner's postcode (the region whose inclusive range contains the postcode, or
601	     * {@code 'UNKNOWN'} when the postcode is absent or in no known range) with the fixed {@code 'V2'}
602	     * version tag appended, e.g. {@code 'NSWV2'}. {@code FY} is the 2-digit fiscal year (the last two
603	     * digits of the calendar year in which the fiscal year of the business-day-adjusted
604	     * registrationDate ends; the fiscal year starts on 1 July). {@code HASH8} is the first eight
605	     * upper-cased hex characters of the SHA-256 of {@code normalizedTelephone + lastName} (the same
606	     * hash used by the region-and-hash identity). {@code CHK} is a single Luhn check digit computed
607	     * over the digits of {@code '<REGION><FY><HASH8>'}, e.g. {@code 'NSWV2261A2B3C4D5'}.
608	     *
609	     * @param postcode the postcode of the owner being created, may be {@code null}
610	     * @param registrationDate the business-day-adjusted registration date of the owner being created
611	     * @param normalizedTelephone the E.164 telephone of the owner being created
612	     * @param lastName the last name of the owner being created
613	     * @return the formatted member id
614	     */
615	    private String memberId(String postcode, LocalDate registrationDate, String normalizedTelephone, String lastName) {
616	        String region = regionFromPostcode(postcode)
617	            + org.springframework.samples.petclinic.util.IdentityKeys.VERSION_TAG;
618	        String fiscalYear = String.format("%02d", fiscalYearEnding(registrationDate) % 100);
619	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
620	        String base = region + fiscalYear + hash8;
621	        return base + luhnCheckDigit(base);
622	    }
623	
624	    /**
625	     * The fiscal year in which a date falls, labelled by the calendar year in which the fiscal year
626	     * ends. The fiscal year starts on 1 July, so a date on or after 1 July belongs to the fiscal year
627	     * ending the following calendar year, and a date before 1 July belongs to the fiscal year ending
628	     * that calendar year.
629	     */
630	    private static int fiscalYearEnding(LocalDate date) {
631	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
632	    }
633	
634	    /**
635	     * The Luhn check digit (0-9) computed over the digits contained in {@code value}; non-digit
636	     * characters are ignored.
637	     */
638	    private static int luhnCheckDigit(String value) {
639	        int sum = 0;
640	        boolean dbl = true;
641	        for (int i = value.length() - 1; i >= 0; i--) {
642	            char c = value.charAt(i);
643	            if (c < '0' || c > '9') {
644	                continue;
645	            }
646	            int d = c - '0';
647	            if (dbl) {
648	                d *= 2;
649	                if (d > 9) {
650	                    d -= 9;
651	                }
652	            }
653	            sum += d;
654	            dbl = !dbl;
655	        }
656	        return (10 - (sum % 10)) % 10;
657	    }
