659	    /**
660	     * The owner's current primary identifier, as carried by the structured {@link OwnerCreatedEvent}:
661	     * its unified {@code memberId}.
662	     *
663	     * @param owner the owner just created
664	     * @return the owner's primary identifier
665	     */
666	    private String primaryIdentifier(Owner owner) {
667	        return owner.getMemberId();
