670	    /**
671	     * De-duplicates a freshly computed member id against the member ids already held by existing
672	     * owners. When the id is unused it is returned unchanged; otherwise {@code '-<n>'} is appended
673	     * with the smallest {@code n} of 2 or more that yields an id no existing owner carries.
674	     *
675	     * @param memberId the computed member id for the owner being created
676	     * @return the same id when unique, otherwise the id with a {@code '-<n>'} suffix that makes it
677	     *     unique
678	     */
679	    private String deduplicateMemberId(String memberId) {
680	        Set<String> existing = new java.util.HashSet<>();
681	        for (Owner owner : this.clinicService.findAllOwners()) {
682	            if (owner.getMemberId() != null) {
683	                existing.add(owner.getMemberId());
684	            }
685	        }
686	        if (!existing.contains(memberId)) {
687	            return memberId;
688	        }
689	        int n = 2;
690	        while (existing.contains(memberId + "-" + n)) {
691	            n++;
692	        }
693	        return memberId + "-" + n;
694	    }
