696	    /**
697	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
698	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
699	     * {@code null}, non-numeric, or in no known range.
700	     *
701	     * @param postcode the postcode, may be {@code null}
702	     * @return the region code, or {@code 'UNKNOWN'}
703	     */
704	    private static String regionFromPostcode(String postcode) {
705	        if (postcode == null || postcode.isBlank()) {
706	            return "UNKNOWN";
707	        }
708	        int code;
709	        try {
710	            code = Integer.parseInt(postcode.trim());
711	        } catch (NumberFormatException e) {
712	            return "UNKNOWN";
713	        }
714	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
715	            int[] range = entry.getValue();
716	            if (code >= range[0] && code <= range[1]) {
717	                return entry.getKey();
718	            }
719	        }
720	        return "UNKNOWN";
721	    }
