723	    /**
724	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
725	     * upper-cased.
726	     *
727	     * @param value the string to hash
728	     * @param length the number of leading hex characters to return
729	     * @return the upper-cased hex prefix of the digest
730	     */
731	    private static String sha256HexPrefix(String value, int length) {
732	        try {
733	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
734	            StringBuilder sb = new StringBuilder(digest.length * 2);
735	            for (byte b : digest) {
736	                sb.append(String.format("%02x", b));
737	            }
738	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
739	        } catch (NoSuchAlgorithmException e) {
740	            throw new IllegalStateException("SHA-256 not available", e);
741	        }
742	    }
