763	    /**
764	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
765	     * number of existing owners already carrying the same {@code householdId}. The household
766	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
767	     * with that identifier) is a household of one. The count includes the owner being created (hence
768	     * the {@code + 1}).
769	     *
770	     * @param householdId the stable household identifier of the owner being created
771	     * @return the number of household members after this create (always at least 1)
772	     */
773	    private int householdSize(String householdId) {
774	        if (householdId == null) {
775	            return 1;
776	        }
777	        return (int) this.clinicService.findAllOwners().stream()
778	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
779	            .count() + 1;
780	    }
