782	    /**
783	     * Computes the household-capped membership level for the owner being created. The level starts as
784	     * the owner's own derived level (from its membership points). When at least one existing (active)
785	     * household member shares the owner's {@code householdId}, the level is capped so it may not exceed
786	     * one above the current maximum membership level among those existing members; with no existing
787	     * household member no cap applies and the derived level is returned unchanged. Returns {@code null}
788	     * when no level can be derived for the owner.
789	     *
790	     * @param owner the owner being created, with its level-affecting fields already populated
791	     * @param householdId the stable household identifier of the owner being created
792	     * @return the capped membership level, or {@code null} when none can be derived
793	     */
794	    private Integer cappedMembershipLevel(Owner owner, String householdId) {
795	        Integer level = ownerMapper.membershipLevel(owner);
796	        if (level == null || householdId == null) {
797	            return level;
798	        }
799	        java.util.OptionalInt maxExisting = activeOwners()
800	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
801	            .map(ownerMapper::membershipLevel)
802	            .filter(java.util.Objects::nonNull)
803	            .mapToInt(Integer::intValue)
804	            .max();
805	        if (maxExisting.isPresent()) {
806	            level = Math.min(level, maxExisting.getAsInt() + 1);
807	        }
808	        return level;
809	    }
