811	    /**
812	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
813	     * lower-casing.
814	     *
815	     * @param value the raw name, may be {@code null}
816	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
817	     */
818	    private static String normalizeName(String value) {
819	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
820	    }
