822	    /**
823	     * The fixed city-to-region table used to validate a postcode against its city
824	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
825	     * therefore accepts any 4-digit postcode.
826	     */
827	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
828	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
829	
830	    /**
831	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
832	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
833	     */
834	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
835	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
836	
837	    /**
838	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
839	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
840	     * when the city maps to a known region, must fall within that region's inclusive range
841	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
842	     * postcode.
843	     *
844	     * @param city the city of the owner being created
845	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
846	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
847	     *     for the city's region
848	     */
849	    private static void validatePostcode(String city, String postcode) {
850	        if (postcode == null || postcode.isBlank()) {
851	            return;
852	        }
853	        if (!postcode.matches("\\d{4}")) {
854	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
855	        }
856	        String region = CITY_REGION.get(city);
857	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
858	        if (range != null) {
859	            int value = Integer.parseInt(postcode);
860	            if (value < range[0] || value > range[1]) {
861	                throw new InvalidPostcodeException(
862	                    "Postcode is out of range for the city's region");
863	            }
864	        }
865	    }
