878	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, if any. The
879	     * header is absent for ordinary creates; when present and non-blank it enables the idempotent-create
880	     * behaviour keyed on its value.
881	     *
882	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
883	     */
884	    private static String currentIdempotencyKey() {
885	        var attributes = org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
886	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
887	            return null;
888	        }
889	        String key = servletAttributes.getRequest().getHeader("Idempotency-Key");
890	        return (key == null || key.isBlank()) ? null : key.trim();
891	    }
