893	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
894	    @Override
895	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
896	        String idempotencyKey = currentIdempotencyKey();
897	        if (idempotencyKey != null) {
898	            Integer existingId = idempotencyKeys.get(idempotencyKey);
899	            if (existingId != null) {
900	                Owner existing = this.clinicService.findOwnerById(existingId);
901	                if (existing != null) {
902	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
903	                }
904	            }
905	        }
906	        applyAddress(ownerFieldsDto);
907	        validateRequiredFields(ownerFieldsDto);
908	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
909	        if (registrationDate == null) {
910	            registrationDate = LocalDate.now();
911	        } else if (registrationDate.isAfter(LocalDate.now())) {
912	            throw new FutureRegistrationDateException(
913	                "registrationDate must not be later than the server date");
914	        }
915	        registrationDate = toBusinessDay(registrationDate);
916	        ownerFieldsDto.setRegistrationDate(registrationDate);
917	        rejectDailyOwnerLimit(registrationDate);
918	        rejectCityAtCapacity(ownerFieldsDto.getCity());
919	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
920	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
921	        ownerFieldsDto.setTelephone(normalizedTelephone);
922	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
923	        ownerFieldsDto.setEmail(normalizedEmail);
924	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
925	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
926	        String identityKey = deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerFieldsDto.getLastName());
927	        rejectDuplicateIdentity(identityKey);
928	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
929	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), identityKey);
930	        HttpHeaders headers = new HttpHeaders();
931	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
932	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
933	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
934	        owner.setMemberId(deduplicateMemberId(memberId(
935	            ownerFieldsDto.getPostcode(), registrationDate, normalizedTelephone, ownerFieldsDto.getLastName())));
936	        owner.setHouseholdId(ownerHouseholdId);
937	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
938	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
939	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
940	        owner.setCapacityWarning(capacityWarning(ownerFieldsDto.getCity()));
941	        owner.setMembershipLevel(cappedMembershipLevel(owner, ownerHouseholdId));
942	        this.clinicService.saveOwner(owner);
943	        if (idempotencyKey != null) {
944	            idempotencyKeys.put(idempotencyKey, owner.getId());
945	        }
946	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
947	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
948	            ownerMapper.membershipLevel(owner));
949	        OwnerDto.OwnerSegmentEnum ownerSegment = ownerMapper.ownerSegment(owner);
950	        AUDIT.info(new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
951	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner),
952	            ownerSegment == null ? null : ownerSegment.getValue()).toJson());
953	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
954	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
955	        headers.setLocation(UriComponentsBuilder.newInstance()
956	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
957	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
958	    }
