963	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
964	        if (currentOwner == null) {
965	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
966	        }
967	        currentOwner.setAddress(ownerFieldsDto.getAddress());
968	        currentOwner.setCity(ownerFieldsDto.getCity());
969	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
970	        currentOwner.setLastName(ownerFieldsDto.getLastName());
971	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
972	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
973	        this.clinicService.saveOwner(currentOwner);
974	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
975	    }
976	
977	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
